import {World,applyDelta} from './world.js';
import {brushOperation,mergeStroke} from './brushes.js';
const names={smooth:'Suavizar',raise:'Elevar',lower:'Rebaixar',flatten:'Nivelar',erode:'Erosão leve',add:'Adicionar blocos',remove:'Escavar',paint:'Pintar superfície'};
export function createBrushEditor({getWorld,getRenderer,isBusy,commit,activate,restore,onError,onHint}){
 const $=s=>document.querySelector(s);let enabled=false,stroke=null,lastTime=0;
 const preset={natural:{mode:'smooth',shape:'sphere',radius:6,strength:6,iterations:4,material:'minecraft:grass_block',mask:'terrain'},mountain:{mode:'raise',shape:'sphere',radius:7,strength:4,iterations:2,material:'minecraft:stone',mask:'terrain'},dig:{mode:'remove',shape:'sphere',radius:4,strength:2,iterations:2,material:'minecraft:air',mask:'terrain'},build:{mode:'add',shape:'cube',radius:0,strength:2,iterations:2,material:'minecraft:stone_bricks',mask:'air'},ball:{mode:'add',shape:'sphere',radius:4,strength:2,iterations:2,material:'minecraft:stone',mask:'terrain'}};
 function options(){return {mode:$('#brush-mode').value,shape:$('#brush-shape').value,radius:Number($('#brush-radius').value),strength:Number($('#brush-strength').value),iterations:Number($('#brush-iterations').value),material:$('#brush-material').value.trim(),mask:$('#brush-mask').value,depth:Number($('#brush-depth').value),levelY:$('#brush-level').value===''?undefined:Number($('#brush-level').value)};}
 function report(text){$('#brush-report').textContent=text;}
 function cancel(){if(!stroke)return;stroke=null;getRenderer().setPickWorld(getWorld());restore();onHint(null);report('Traço cancelado. Nenhuma alteração aplicada.');}
 function center(hit,o){return hit.point.map((v,i)=>v+(o.mode==='add'?hit.normal[i]:0));}
 function dab(hit,force=false){if(!stroke||!hit)return;const now=performance.now();if(!force&&now-lastTime<75)return;lastTime=now;
  const o=stroke.options,p=center(hit,o);if(!stroke.working.inside(...p))return;const previous=stroke.last||p,distance=Math.hypot(...p.map((v,i)=>v-previous[i])),steps=Math.min(8,Math.max(1,Math.ceil(distance/Math.max(1,o.radius*.6))));
  for(let step=1;step<=steps;step++){const point=p.map((v,i)=>Math.round(previous[i]+(v-previous[i])*step/steps));if(stroke.last?.every((v,i)=>v===point[i]))continue;if(stroke.ops.length>=128)break;
   const op=brushOperation(stroke.working,point,o);if(op.delta.length){applyDelta(stroke.working,op);stroke.ops.push(op);}stroke.last=point;
  }
  const merged=mergeStroke(stroke.base,stroke.ops);getRenderer().setGhost(null);getRenderer().setWorld(stroke.working,Number($('#cut').value));getRenderer().setPickWorld(stroke.base);getRenderer().setCursor(p,o.radius,o.shape);
  report(`${merged.delta.length.toLocaleString('pt-BR')} posições na prévia do traço. Solte para aplicar; Esc cancela.${stroke.ops.length>=128?' Limite de 128 amostras atingido; comece outro traço.':''}`);$('#brush-position').textContent=p.join(', ');onHint('PINCEL · PRÉVIA');
 }
 function start(hit){if(isBusy()||!hit||!getWorld())return;try{const o=options();stroke={base:getWorld(),working:World.from(getWorld().snapshot()),ops:[],last:null,options:o};dab(hit,true);}catch(e){cancel();onError(e);}}
 function move(hit){try{dab(hit);}catch(e){cancel();onError(e);}}
 async function end(hit){if(!stroke)return;try{dab(hit,true);const op=mergeStroke(stroke.base,stroke.ops),label=names[stroke.options.mode];stroke=null;getRenderer().setPickWorld(getWorld());await commit({...op,label:`Pincel ${label}`});onHint(null);report(op.delta.length?`${label}: ${op.delta.length.toLocaleString('pt-BR')} posições aplicadas. Desfazer disponível.`:'Nenhuma alteração. Confira a máscara, a força e a proteção de construções.');}catch(e){stroke=null;restore();onHint(null);onError(e);}}
 function hover(hit){if(stroke||!enabled||isBusy())return;const r=getRenderer();if(!hit){r.setCursor(null);return;}const o=options(),p=center(hit,o);r.setCursor(p,o.radius,o.shape);$('#brush-position').textContent=p.join(', ');}
 function enable(){if(!getWorld()){onError(Error('Gere o terreno antes de usar os pincéis.'));return;}activate();enabled=true;getRenderer().setInteraction({mode:'brush',onStart:start,onMove:move,onEnd:end,onCancel:cancel,onHover:hover});$('#brush-active').textContent='Pincel ativo · arraste no mapa';report('Arraste para editar. Alt + arraste orbita; Shift + arraste move a câmera.');}
 function disable(){cancel();enabled=false;if($('#brush-active'))$('#brush-active').textContent='Pincel inativo';}
 const tab=document.createElement('button');tab.id='tab-brush';tab.setAttribute('role','tab');tab.setAttribute('aria-selected','false');tab.textContent='Pincéis';$('.inspector-tabs').append(tab);
 const panel=document.createElement('div');panel.id='brush-properties';panel.className='inspector-content';panel.hidden=true;panel.innerHTML=`<section class="property-section"><h3>✎ Pincéis de criação</h3><p class="field-help">Ferramentas nativas inspiradas em WorldEdit e VoxelSniper. Não executam plugins nem importam scripts de pincéis.</p><label>Preset<select id="brush-preset"><option value="natural">Suavização natural</option><option value="mountain">Elevar montanha</option><option value="dig">Escavar terreno</option><option value="build">Construir bloco a bloco</option><option value="ball">Esfera de pedra</option></select></label><label>Operação<select id="brush-mode">${Object.entries(names).map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select></label><label>Forma<select id="brush-shape"><option value="sphere">Esfera / disco de relevo</option><option value="cube">Cubo / área quadrada</option><option value="cylinder">Cilindro vertical</option><option value="hollow">Esfera oca</option></select></label><label>Material<input id="brush-material" value="minecraft:grass_block" list="brush-materials" maxlength="160"></label><datalist id="brush-materials">${['grass_block','stone','dirt','sand','gravel','stone_bricks','deepslate_bricks','oak_planks','glass','oak_log'].map(v=>`<option value="minecraft:${v}">`).join('')}</datalist><label>Máscara<select id="brush-mask"><option value="terrain">Terreno · preservar construções</option><option value="air">Somente ar</option><option value="solid">Somente blocos existentes</option><option value="all">Todos · permite substituir estruturas</option></select></label></section><section class="property-section"><h3>◯ Alcance e intensidade</h3><label class="range-heading">Raio <output id="brush-radius-value">6</output><input id="brush-radius" type="range" min="0" max="12" value="6"></label><label class="range-heading">Força <output id="brush-strength-value">6</output><input id="brush-strength" type="range" min="1" max="6" value="6"></label><div class="two-cols"><label>Passagens<select id="brush-iterations">${[1,2,3,4,5,6].map(n=>`<option value="${n}"${n===4?' selected':''}>${n}</option>`).join('')}</select></label><label>Profundidade da pintura<select id="brush-depth">${[1,2,3,4,5,6].map(n=>`<option value="${n}">${n} bloco(s)</option>`).join('')}</select></label></div><label>Cota Y para nivelar<input id="brush-level" type="number" min="0" max="79" placeholder="Usar altura clicada"></label><button id="brush-enable" class="button primary full" style="margin-top:16px">✎ Ativar pincel</button><p id="brush-active" class="field-help">Pincel inativo</p><p class="field-help">Centro: <span id="brush-position">—</span>. Raio 0 edita um bloco. Soltar aplica um traço inteiro; Esc cancela.</p><p id="brush-report" class="field-help"></p></section>`;$('.inspector').append(panel);
 tab.onclick=enable;$('#brush-enable').onclick=enable;
 for(const key of ['radius','strength'])$('#brush-'+key).oninput=()=>{$('#brush-'+key+'-value').textContent=$('#brush-'+key).value;};
 $('#brush-preset').onchange=()=>{cancel();const p=preset[$('#brush-preset').value];for(const [k,v]of Object.entries(p))$('#brush-'+k).value=v;for(const key of ['radius','strength'])$('#brush-'+key+'-value').textContent=$('#brush-'+key).value;report('Preset carregado. Clique em Ativar pincel para editar.');};
 for(const input of panel.querySelectorAll('input,select'))input.addEventListener('change',()=>{if(stroke)cancel();});
 return {enable,disable,cancel,get active(){return enabled;}};
}
